CREATE OR REPLACE FUNCTION public.payment_policy_current() RETURNS public.publisher_payment_policy LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE p public.publisher_payment_policy; BEGIN SELECT * INTO p FROM public.publisher_payment_policy WHERE id; IF NOT FOUND THEN INSERT INTO public.publisher_payment_policy(id) VALUES(true) RETURNING * INTO p; END IF; RETURN p; END $$;
REVOKE ALL ON FUNCTION public.payment_policy_current() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.payment_policy_current() TO service_role;
CREATE OR REPLACE FUNCTION public.payment_notify(u uuid,t text,b text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$ INSERT INTO public.notifications(user_id,title,body,kind) VALUES(u,t,b,'payment'); $$;
REVOKE ALL ON FUNCTION public.payment_notify(uuid,text,text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.payment_balances(u uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE p public.publisher_payment_policy; finalized numeric; reserved numeric; paid numeric; available numeric; eligible boolean; account public.publisher_payment_accounts; BEGIN
p:=public.payment_policy_current(); SELECT coalesce(sum(amount),0) INTO finalized FROM public.publisher_payment_events WHERE user_id=u AND kind IN ('finalized','adjustment_reversal'); SELECT coalesce(sum(amount),0) INTO reserved FROM public.payments WHERE user_id=u AND ledger_managed AND coalesce(lifecycle_status,status::text) NOT IN ('failed_reconciled','rejected'); SELECT coalesce(sum(amount),0) INTO paid FROM public.payments WHERE user_id=u AND status='paid'; available:=greatest(0,finalized-reserved); SELECT * INTO account FROM public.publisher_payment_accounts WHERE user_id=u;
eligible:=available>=p.minimum AND coalesce(account.verified,false) AND NOT coalesce(account.on_hold,false) AND EXISTS(SELECT 1 FROM public.profiles WHERE id=u AND status='active' AND kyc_status='verified') AND NOT EXISTS(SELECT 1 FROM public.publisher_earnings_batches WHERE user_id=u AND (investigation_open OR reconciliation_open)) AND NOT EXISTS(SELECT 1 FROM public.payments WHERE user_id=u AND NOT ledger_managed AND status IN ('pending','processing','approved'));
RETURN jsonb_build_object('estimated',coalesce((SELECT sum(gross)::text FROM public.publisher_earnings_batches WHERE user_id=u AND status<>'finalized'),'0'),'verification',coalesce((SELECT sum(net)::text FROM public.publisher_earnings_batches WHERE user_id=u AND status<>'finalized'),'0'),'finalized',available::text,'available',CASE WHEN eligible THEN available::text ELSE '0' END,'paid',paid::text,'adjustments',coalesce((SELECT sum(amount)::text FROM public.publisher_earnings_adjustments WHERE user_id=u AND reversed_at IS NULL),'0'),'eligible',eligible,'account',to_jsonb(account)); END $$;
REVOKE ALL ON FUNCTION public.payment_balances(uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.payment_ingest() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE p public.publisher_payment_policy; r record; b public.publisher_earnings_batches; BEGIN
p:=public.payment_policy_current(); FOR r IN SELECT user_id,'website'::text source,date AS earning_day,sum(revenue*pr.revenue_share/100)::numeric(20,6) gross FROM public.revenue_events e JOIN public.profiles pr ON pr.id=e.user_id WHERE site_id IS NOT NULL AND date>=(p.effective_at AT TIME ZONE 'UTC')::date GROUP BY user_id,date UNION ALL SELECT n.user_id,'smartlink',stat_date,sum(n.revenue*pr.revenue_share/100)::numeric(20,6) FROM public.network_stats n JOIN public.profiles pr ON pr.id=n.user_id WHERE n.source='api' AND stat_date>=(p.effective_at AT TIME ZONE 'UTC')::date GROUP BY n.user_id,stat_date LOOP
PERFORM pg_advisory_xact_lock(hashtext(r.user_id::text)); SELECT * INTO b FROM public.publisher_earnings_batches WHERE user_id=r.user_id AND source=r.source AND period_start=r.earning_day AND period_end=r.earning_day FOR UPDATE;
IF NOT FOUND THEN INSERT INTO public.publisher_earnings_batches(user_id,source,period_start,period_end,gross,verification_ends_at) VALUES(r.user_id,r.source,r.earning_day,r.earning_day,greatest(0,r.gross),greatest(now(),(r.earning_day+1)::timestamp AT TIME ZONE 'UTC')+make_interval(days=>p.verification_days)) RETURNING * INTO b; INSERT INTO public.publisher_payment_events(user_id,batch_id,kind,amount,reason,idempotency_key) VALUES(r.user_id,b.id,'estimated',b.gross,'Source earnings entered verification','batch:'||b.id); PERFORM public.payment_notify(r.user_id,'Earnings entered verification','Batch '||b.id||' is under quality verification.');
ELSIF b.gross<>r.gross THEN IF b.status='finalized' OR r.gross<b.adjustment THEN UPDATE public.publisher_earnings_batches SET reconciliation_open=true,status='on_hold' WHERE id=b.id; ELSE INSERT INTO public.publisher_payment_events(user_id,batch_id,kind,amount,reason,idempotency_key) VALUES(r.user_id,b.id,'estimate_revision',r.gross-b.gross,'Provider estimate reconciliation',gen_random_uuid()::text); UPDATE public.publisher_earnings_batches SET gross=r.gross,approved=false,verification_started_at=now(),verification_ends_at=greatest(verification_ends_at,now()+make_interval(days=>p.verification_days)) WHERE id=b.id; END IF; END IF; END LOOP;
-- Source removals must hold existing batches rather than silently credit stale reports.
UPDATE public.publisher_earnings_batches b SET reconciliation_open=true,status='on_hold' WHERE b.source IN ('website','smartlink') AND b.period_start>=(p.effective_at AT TIME ZONE 'UTC')::date AND NOT EXISTS(SELECT 1 FROM public.revenue_events e WHERE b.source='website' AND e.user_id=b.user_id AND e.site_id IS NOT NULL AND e.date=b.period_start) AND NOT EXISTS(SELECT 1 FROM public.network_stats n WHERE b.source='smartlink' AND n.user_id=b.user_id AND n.source='api' AND n.stat_date=b.period_start);
END $$;
REVOKE ALL ON FUNCTION public.payment_ingest() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.payment_ingest() TO service_role;
CREATE OR REPLACE FUNCTION public.payment_tick() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE b record; p public.publisher_payment_policy; BEGIN
PERFORM public.payment_ingest(); p:=public.payment_policy_current(); FOR b IN SELECT * FROM public.publisher_earnings_batches WHERE status='under_verification' AND approved AND NOT investigation_open AND NOT reconciliation_open AND verification_ends_at<=now() AND NOT EXISTS(SELECT 1 FROM public.publisher_adjustment_appeals a JOIN public.publisher_earnings_adjustments x ON x.id=a.adjustment_id WHERE x.batch_id=publisher_earnings_batches.id AND a.status='pending') FOR UPDATE SKIP LOCKED LOOP
UPDATE public.publisher_earnings_batches SET status='finalized',finalized_at=now() WHERE id=b.id; INSERT INTO public.publisher_payment_events(user_id,batch_id,kind,amount,reason,idempotency_key) VALUES(b.user_id,b.id,'finalized',b.net,'Verification completed and approved','finalized:'||b.id) ON CONFLICT(idempotency_key) DO NOTHING; PERFORM public.payment_notify(b.user_id,'Verification completed — balance finalized','Verified earnings are finalized.'); IF (public.payment_balances(b.user_id)->>'finalized')::numeric>=p.minimum THEN PERFORM public.payment_notify(b.user_id,'Minimum payout threshold reached','Finalized balance has reached the payout threshold; account eligibility is still required.'); END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.payment_tick() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.payment_tick() TO service_role;
CREATE OR REPLACE FUNCTION public.payment_source_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN PERFORM public.payment_ingest(); RETURN NULL; END $$;
CREATE TRIGGER payment_website_source AFTER INSERT OR UPDATE OR DELETE ON public.revenue_events FOR EACH STATEMENT EXECUTE FUNCTION public.payment_source_changed();
CREATE TRIGGER payment_network_source AFTER INSERT OR UPDATE ON public.publisher_earnings FOR EACH STATEMENT EXECUTE FUNCTION public.payment_source_changed();